from scipy.optimize import minimize
ffs=[]
for r in frags:
 m=r[2]; props=AllChem.MMFFGetMoleculeProperties(m);ff=AllChem.MMFFGetMoleculeForceField(m,props,ignoreInterfragInteractions=True)
 ffs.append(ff)
natoms=len(all_xyz)
groups=[]
for i in range(4):
 for j in range(i+1,4):
  for a in range(idx[i],idx[i+1]):
   if all_sym[a]=='H':continue
   for b in range(idx[j],idx[j+1]):
    if all_sym[b]=='H':continue
    radius={'C':1.77,'N':1.52,'P':1.87}
    groups.append((a,b,radius[all_sym[a]]+radius[all_sym[b]]))
pair=np.array(groups)
pa=pair[:,0].astype(int); pb=pair[:,1].astype(int); mind=pair[:,2]
zind=natoms-2; cind=natoms-1
bonds=[(idx[0]+0,zind,1.98,90),(idx[1]+0,zind,2.04,95),(idx[2]+10,zind,2.2,80),(idx[2]+19,zind,2.2,80),(idx[1]+10,cind,2.29,90),(idx[2]+11,cind,2.29,90),(idx[2]+20,cind,2.29,90),(idx[3]+0,cind,1.86,100),(zind,cind,2.60,95)]
weak=[(0,0,Tph[0],7),(1,0,Tbot[0],5),(1,10,Tbot[1],5),(2,10,Ttop[0],4),(2,19,Ttop[2],4),(2,11,Ttop[1],4),(2,20,Ttop[3],4),(2,9,Ttop[4],2),(2,18,Ttop[5],2),(3,0,Tiso[0],10),(3,1,Tiso[1],10),(3,2,Tiso[2],10)]

def func(v):
 x=v.reshape((-1,3)); grad=np.zeros_like(x);e=0
 for i,ff in enumerate(ffs):
  xx=x[idx[i]:idx[i+1]].ravel().tolist()
  e+=ff.CalcEnergy(xx)
  grad[idx[i]:idx[i+1]]+=np.array(ff.CalcGrad(xx)).reshape((-1,3))
 for a,b,d,k in bonds:
  vec=x[a]-x[b];r=np.linalg.norm(vec)+1e-12;dv=r-d;e+=k*dv**2;g=(2*k*dv/r)*vec;grad[a]+=g;grad[b]-=g
 diff=x[pa]-x[pb];r=np.maximum(np.linalg.norm(diff,axis=1),.0001);dv=np.minimum(0,r-mind);e+=12*np.sum(dv**2);g=24*(dv/r)[:,None]*diff;np.add.at(grad,pa,g);np.add.at(grad,pb,-g)
 for frag,atom,p,k in weak:
  a=idx[frag]+atom;vec=x[a]-p;e+=k*vec@vec;grad[a]+=2*k*vec
 for a,target in [(zind,Zr),(cind,Co)]:
  vec=x[a]-target;e+=60*vec@vec;grad[a]+=120*vec
 return e,grad.flatten()
print('initial energy',func(all_xyz.flatten())[0],flush=True)
res=minimize(func,all_xyz.flatten(),jac=True,method='L-BFGS-B',options={'maxiter':700,'ftol':5e-10})
print('optimized',res.success,res.message,'iterations',res.nit,'energy',res.fun,flush=True)
x=res.x.reshape((-1,3))
for a,b,d,k in bonds:print('bond',all_sym[a],all_sym[b],np.linalg.norm(x[a]-x[b]),'goal',d)
print('interfrag minimum', min(np.linalg.norm(x[pa]-x[pb],axis=1)))
# remove one hydrogen from each bound nitrogen: closest to its metal site, leaving the Ph N-H substituent
remove=[]
for frag, nidx in [(0,0),(1,0),(2,10),(2,19)]:
 m=frags[frag][2];atom=m.GetAtomWithIdx(nidx);hs=[a.GetIdx() for a in atom.GetNeighbors() if a.GetSymbol()=='H'];
 print('N',frag,nidx,'H',hs)
 chosen=min(hs,key=lambda h:np.linalg.norm(x[idx[frag]+h]-x[zind]))
 remove.append(idx[frag]+chosen)
with open('answer.xyz','w') as f:
 f.write(str(natoms-len(remove))+'\nZr-Co isocyanide tris(diisopropylphosphine) complex with nitrogen ligands; Angstrom\n')
 for k in range(natoms):
  if k not in remove:
   p=x[k]; f.write('%-2s %14.8f %14.8f %14.8f\n'%(all_sym[k],*p))
print('answer.xyz written',natoms-len(remove),'atoms')
